#if UNITY_EDITOR
using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
namespace FashionFit.Editor {
 public static class ResponseReadoutVerification {
  [Serializable]sealed class Result{public string status="passed",scope="Native material reduction versus original managed reading on male/female fitted outfits, four materials, neutral/pull/recovery; same calibrated edge reference";public int checks,states;public float maxStrainError,maxTensionError;}
  static Result r;static void Compare(ElasticSurface surface){var native=surface.Reading;typeof(ElasticSurface).GetMethod("UpdateReading",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(surface,null);var reference=surface.Reading;r.states++;CompareValue(native.tensileStrain,reference.tensileStrain,false);CompareValue(native.compressiveStrain,reference.compressiveStrain,false);CompareValue(native.peakTensileStrain,reference.peakTensileStrain,false);CompareValue(native.peakCompressiveStrain,reference.peakCompressiveStrain,false);CompareValue(native.tensionNm,reference.tensionNm,true);CompareValue(native.compressionNm,reference.compressionNm,true);r.checks++;if(native.rms!=reference.rms||native.hasStiffness!=reference.hasStiffness)throw new Exception("Reading mode mismatch");}
  static void CompareValue(float a,float b,bool force){r.checks++;float error=Mathf.Abs(a-b);if(force)r.maxTensionError=Mathf.Max(r.maxTensionError,error);else r.maxStrainError=Mathf.Max(r.maxStrainError,error);float tolerance=(force?.0001f:.000002f)+Mathf.Abs(b)*.00002f;if(float.IsNaN(a)||float.IsInfinity(a)||error>tolerance)throw new Exception("Native reading mismatch "+a+" versus "+b+" error "+error);}
  public static void RunBatch(){string output=Path.GetFullPath("Verification/ResponseOptimization");Directory.CreateDirectory(output);GameObject root=null;r=new Result();try{root=new GameObject("Native readout equivalence");var app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,null);if(!app.Ready)throw new Exception(app.FatalError);for(int gender=0;gender<2;gender++){app.PoseStudio.Wear(gender,5);var wear=app.PoseStudio.Wearables[gender];for(int material=0;material<4;material++){var surface=wear.Surface;surface.SetMaterial(MembraneMaterial.Presets[material]);surface.ResetShape();for(int i=0;i<12;i++)wear.Step(1f/60);Compare(surface);var points=surface.CurrentPoints;int best=0;float d=float.PositiveInfinity;for(int i=0;i<points.Length;i++){float q=(points[i]-new Vector3(-.1f,1.28f,.23f)).sqrMagnitude;if(q<d){d=q;best=i;}}Vector3 p=surface.transform.TransformPoint(points[best]);if(!surface.BeginGrip(0,p))throw new Exception("No direct cloth point");surface.MoveGrip(0,p+Vector3.forward*.30f);for(int i=0;i<65;i++)wear.Step(1f/60);Compare(surface);surface.EndGrip(0);for(int i=0;i<160;i++)wear.Step(1f/60);Compare(surface);}}UnityEngine.Object.DestroyImmediate(root);root=null;File.WriteAllText(output+"/native_readout.json",JsonUtility.ToJson(r,true));EditorApplication.Exit(0);}catch(Exception e){r.status="failed";File.WriteAllText(output+"/native_readout.json",JsonUtility.ToJson(r,true));File.WriteAllText(output+"/readout_failure.txt",e.ToString());if(root)UnityEngine.Object.DestroyImmediate(root);Debug.LogException(e);EditorApplication.Exit(1);}}
 }
}
#endif
